#!/usr/bin/env python3
import html,json,pathlib,shutil
R=pathlib.Path(__file__).resolve().parents[1]; O=R/'dist'
A=json.loads((R/'content/app.json').read_text()); F=json.loads((R/'content/features.json').read_text()); Q=json.loads((R/'content/faq.json').read_text()); B=A['website_url'].rstrip('/')
T={'en':{'about':'About','features':'Features','faq':'FAQ','cta':'Explore on Google Play','tag':'JOB OPPORTUNITY INTELLIGENCE','sub':'Discover opportunities with more context.','gallery':'A look inside the app','download':'Start discovering','privacy':'Privacy policy','support':'Support','meta':'Discover fresh job signals, explore opportunity intelligence and organize interesting roles with Job Connect.'},'ar':{'about':'عن التطبيق','features':'المزايا','faq':'الأسئلة الشائعة','cta':'استكشف التطبيق على Google Play','tag':'ذكاء اكتشاف فرص العمل','sub':'اكتشف الفرص مع فهم أعمق لتفاصيلها.','gallery':'نظرة إلى واجهة التطبيق','download':'ابدأ اكتشاف الفرص','privacy':'سياسة الخصوصية','support':'الدعم','meta':'اكتشف إشارات الوظائف الحديثة وذكاء الفرص ونظّم الوظائف المهمة مع Job Connect.'}}
CSS="""*{box-sizing:border-box}body{margin:0;background:#080b12;color:#f4f7fb;font:16px/1.75 system-ui,sans-serif}a{color:inherit}header,main,footer{width:min(1120px,calc(100% - 36px));margin:auto}header{display:flex;justify-content:space-between;align-items:center;gap:18px;padding:22px 0;border-bottom:1px solid #263246}.brand{font-weight:900;text-decoration:none;letter-spacing:.08em}.brand b,.tag{color:#00c4df}nav{display:flex;gap:22px;flex-wrap:wrap}nav a{color:#c4ccda;text-decoration:none}.hero{padding:70px 0;display:grid;grid-template-columns:1fr .8fr;gap:44px;align-items:center}.tag{font-size:.8rem;letter-spacing:.16em;font-weight:700}.hero h1{font-size:clamp(3rem,7vw,5.7rem);line-height:1;margin:18px 0}.lead,.muted{color:#aab6c8}.btn{display:inline-block;background:#00c4df;color:#061018;text-decoration:none;padding:13px 20px;border-radius:9px;font-weight:800;margin-top:20px}.preview{padding:16px;background:#121a28;border:1px solid #29364b;border-radius:22px;text-align:center}.preview img{height:480px;max-width:100%;object-fit:contain;border-radius:12px}.section{padding:48px 0;border-top:1px solid #ffffff18}.section h2{font-size:2rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.item,.faq{background:#111925;border:1px solid #283449;border-radius:14px;padding:22px}.item h3,.faq h3{margin-top:0}.item p,.faq p{color:#aab6c8}.num{color:#00c4df;font:700 .8rem monospace}.faqgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.end{text-align:center;background:#11242d;border:1px solid #236071;border-radius:18px;padding:34px}footer{padding:30px 0;color:#aab6c8;border-top:1px solid #ffffff18;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}html[dir=rtl] body{text-align:right}html[dir=rtl] header{direction:rtl}@media(max-width:760px){.hero{grid-template-columns:1fr;padding:42px 0}.preview img{height:360px}.grid,.faqgrid{grid-template-columns:1fr}header{align-items:flex-start;flex-direction:column}nav{gap:14px}}"""
def e(x):return html.escape(str(x),quote=True)
def make(lang,sec):
 t=T[lang]; rtl=lang=='ar'; path='' if sec=='home' else sec; can=f'{B}/{lang}/'+(f'{path}/' if path else '')
 nav=''.join(f'<a href="{("../" if path else "")}{p}/">{t[k]}</a>' for p,k in [('about','about'),('features','features'),('faq','faq')])
 switch=f'<a href="{B}/{"en" if rtl else "ar"}/{path+"/" if path else ""}">{"English" if rtl else "العربية"}</a>'
 ld={'@context':'https://schema.org','@type':'MobileApplication','name':A['name'],'operatingSystem':'Android','applicationCategory':'BusinessApplication','description':A['description'][lang],'downloadUrl':A['google_play_url'],'url':can,'author':{'@type':'Organization','name':A['developer']}}
 hero=f'<section class="hero"><div><div class="tag">{t["tag"]}</div><h1>JOB<br>CONNECT<span style="color:#00c4df">.</span></h1><h2>{e(A["tagline"][lang])}</h2><p class="lead">{e(A["description"][lang])}</p><a class="btn" href="{A["google_play_url"]}">{t["cta"]}</a></div><div class="preview"><img src="{("../../" if path else "../")}assets/screens/screen-1.webp" alt="Job Connect job discovery screen"></div></section>'
 feats=''.join(f'<article class="item"><div class="num">0{i+1} / SIGNAL</div><h3>{e(x["title"][lang])}</h3><p>{e(x["description"][lang])}</p></article>' for i,x in enumerate(F))
 faqs=''.join(f'<article class="faq"><h3>{e(x["q"][lang])}</h3><p>{e(x["a"][lang])}</p></article>' for x in Q)
 body=hero+f'<section class="section"><h2>{t["features"]}</h2><div class="grid">{feats}</div></section><section class="section"><h2>{t["faq"]}</h2><div class="faqgrid">{faqs}</div></section><section class="section"><div class="end"><h2>{t["download"]}</h2><p>{e(A["tagline"][lang])}</p><a class="btn" href="{A["google_play_url"]}">{t["cta"]}</a></div></section>'
 return f'<!doctype html><html lang="{lang}" dir="{"rtl" if rtl else "ltr"}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Job Connect — {e(t["sub"])}</title><meta name="description" content="{e(t["meta"])}"><link rel="canonical" href="{can}"><link rel="alternate" hreflang="en" href="{B}/en/{path+"/" if path else ""}"><link rel="alternate" hreflang="ar" href="{B}/ar/{path+"/" if path else ""}"><link rel="alternate" hreflang="x-default" href="{B}/en/{path+"/" if path else ""}"><meta property="og:title" content="Job Connect"><meta property="og:description" content="{e(t["meta"])}"><meta property="og:url" content="{can}"><link rel="stylesheet" href="{("../../" if path else "../")}assets/style.css"><script type="application/ld+json">{json.dumps(ld,ensure_ascii=False)}</script></head><body><header><a class="brand" href="{("../" if path else "")}">JOB <b>CONNECT</b></a><nav>{nav}{switch}</nav></header><main>{body}</main><footer><span>© DevImpact · JOB CONNECT</span><span><a href="{A["privacy_policy_url"]}">{t["privacy"]}</a> · <a href="mailto:{A["support_email"]}">{t["support"]}</a></span></footer></body></html>'
def write(p,s):q=O/p;q.parent.mkdir(parents=True,exist_ok=True);q.write_text(s,encoding='utf-8')
def main():
 if O.exists():shutil.rmtree(O)
 write(pathlib.Path('assets/style.css'),CSS);shutil.copytree(R/'assets/screens',O/'assets/screens')
 for l in ('en','ar'):
  for s in ('home','about','features','faq'):write(pathlib.Path(l)/('' if s=='home' else s)/'index.html',make(l,s))
 write(pathlib.Path('index.html'),f'<!doctype html><html><head><meta charset="utf-8"><title>Job Connect</title><link rel="alternate" hreflang="en" href="{B}/en/"><link rel="alternate" hreflang="ar" href="{B}/ar/"></head><body><a href="./en/">English</a> · <a href="./ar/">العربية</a></body></html>')
 write(pathlib.Path('robots.txt'),f'User-agent: *\nAllow: /\nSitemap: {B}/sitemap.xml\n')
 urls=[f'{B}/{l}/{s+"/" if s else ""}' for l in ('en','ar') for s in ('','about','features','faq')]
 write(pathlib.Path('sitemap.xml'),'<?xml version="1.0"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+e(u)+'</loc></url>' for u in urls)+'</urlset>')
 write(pathlib.Path('llms.txt'),f'# Job Connect\n\n{A["description"]["en"]}\n\n- Google Play: {A["google_play_url"]}\n- English: {B}/en/\n- Arabic: {B}/ar/\n')
if __name__=='__main__':main()
